func:
// one appliance: its room, photo, type plate (and what the phone read on it), note
const d = msg.data;
const record = {
  edge: msg.edge, at: new Date(msg.payload.ts * 1000).toISOString(), kind: d.kind, room: d.room,
  plate_text: d.plate && d.plate.text || '', note: d.note || '',
  photos: { appliance: d.photo && d.photo.jpeg, plate: d.plate && d.plate.jpeg }   // base64 JPEGs
};
msg.payload = record;
msg.method = 'POST';
msg.url = (env.get('DHC_API') || 'http://127.0.0.1:1880/dhc-mock') + '/inventory';
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// saved (or not): a toast, and the 'Recorded' tile counts
if (msg.statusCode >= 200 && msg.statusCode < 300) {
  const n = (flow.get('count') || 0) + 1;
  flow.set('count', n);
  return [{ payload: { en: 'Saved ✓', fr: 'Enregistré ✓', de: 'Gespeichert ✓' } }, { payload: n, tile: 'count', label: 'today' }];
}
return [{ payload: { en: 'Not saved: ' + msg.statusCode, fr: 'Non enregistré : ' + msg.statusCode, de: 'Nicht gespeichert: ' + msg.statusCode } }, null];

// the plate read on the phone, said back
const t = (msg.data.plate_only || {}).text || '';
return { payload: t ? t.split('\n')[0] : 'No text', lang: msg.payload.lang };

// a scanned tag: known appliances are kept in flow context by their code (fill it from DigitalHome.cloud)
const code = (msg.data.tag || {}).code;
const known = flow.get('tags') || {};
msg.payload = known[code] ? { en: known[code], fr: known[code], de: known[code] } : { en: 'Not in the inventory yet: ' + code, fr: 'Pas encore inventorié : ' + code, de: 'Noch nicht erfasst: ' + code };
return msg;

msg.statusCode = 201;
msg.payload = { id: 'appl-' + Date.now(), room: msg.payload.room };
return msg;
